<script setup lang="ts">import{ref}from'vue';import{api}from'../../services/api';import PageHeader from'../../components/PageHeader.vue';const title=ref('');const noCamera=ref(false);const room=ref<any>(null);const error=ref('');async function create(){if(!title.value.trim()){error.value='请输入直播标题';return;}try{const{data}=await api.post('/live/rooms',{title:title.value,viewerCoins:20,secondViewCoins:30,noCamera:noCamera.value});room.value=data;}catch(e:any){error.value=e?.response?.data?.message??'创建失败';}}async function action(name:string){const{data}=await api.post(`/live/rooms/${room.value.id}/${name}`);room.value=data;}</script><template><main class="page business-page studio-page"><PageHeader title="直播工作台" subtitle="直播互动 · 第二视角"/><section v-if="!room" class="form-panel"><label>直播标题<input v-model="title" aria-label="直播标题" placeholder="今天和大家聊什么"></label><label class="switch-row"><input v-model="noCamera" aria-label="使用演示视频" type="checkbox"><span><b>使用演示视频</b><small>无摄像头或本地演示时启用</small></span></label><button class="primary-button wide" @click="create">创建直播间</button><p v-if="error" class="form-error">{{error}}</p></section><section v-else class="studio-card"><div class="preview"><span>{{room.status}}</span><div>LIVE<br>PREVIEW</div></div><h2>{{title}}</h2><p v-if="noCamera" class="success-note">演示视频回退已启用</p><p class="stream-url">{{room.playbackUrl}}</p><div class="action-grid"><button v-if="room.status==='CREATED'" @click="action('start')">开始直播</button><button v-if="room.status==='LIVE'" @click="action('disconnect')">模拟断线</button><button v-if="room.status==='RECONNECTING'" @click="action('reconnect')">重新连接</button><button v-if="room.status!=='ENDED'" class="danger" @click="action('end')">结束直播</button></div></section></main></template>
